#!/usr/bin/env node
// Ecosystem example: consume a dsh-self memory directory from another
// Node plugin without shelling out to the CLI.
//
//   node examples/consumer.mjs <workspace-dir> [memory]
//
// It shows the two integration routes the package promises:
//   1. read the locked markdown format with the exported parsers
//   2. read the handoff JSON sidecar generated by `handoff`
//
// This file is documentation, not part of the plugin runtime.

import path from 'node:path';
import { readdir, readFile } from 'node:fs/promises';

import { hotStats, parseCards, parseIndex, parseJudgmentsTable } from 'dsh-self/format';

const workspace = path.resolve(process.argv[2] ?? process.cwd());
const memoryDir = process.argv[3] ?? 'memory';
const root = path.resolve(workspace, memoryDir);

async function readIfExists(file) {
  try {
    return await readFile(file, 'utf8');
  } catch {
    return undefined;
  }
}

const hotText = await readIfExists(path.join(root, 'hot', 'state.md'));
const judgmentsText = await readIfExists(path.join(root, 'judgments.md'));
const cardsText = await readIfExists(path.join(root, 'judgments-cards.md'));
const indexText = await readIfExists(path.join(root, 'index.md'));
const handoffDir = path.join(root, 'handoffs');

const hot = hotStats(hotText ?? '');
const judgments = parseJudgmentsTable(judgmentsText ?? '');
const cards = parseCards(cardsText ?? '');
const index = parseIndex(indexText ?? '');

console.log(`memory root: ${root}`);
console.log(`hot: ${hot.chars} chars / ${hot.bytes} B`);
console.log(`judgments: ${judgments.rows.length} (issues: ${judgments.issues.length})`);
console.log(`cards: ${cards.length}`);
console.log(`index entries: ${index.rows.length}`);

let handoffFiles = [];
try {
  handoffFiles = (await readdir(handoffDir)).filter((name) => /^handoff-.*\.json$/.test(name)).sort();
} catch {
  handoffFiles = [];
}
console.log(`handoff sidecars: ${handoffFiles.length}`);
if (handoffFiles.length > 0) {
  const latest = JSON.parse(await readFile(path.join(handoffDir, handoffFiles[handoffFiles.length - 1]), 'utf8'));
  console.log(`latest handoff: ${latest.generatedAt} · schema=${latest.schema} · questions=${latest.verificationQuestions.length}`);
}

// Example: a plugin that only needs "the top 3 most trusted judgments".
const trusted = judgments.rows
  .filter((row) => row.status === 'instinct' || row.status === 'common')
  .slice(0, 3)
  .map((row) => `${row.id} ${row.conclusion}`);
console.log('top judgments:', trusted.length > 0 ? trusted : '(none yet)');
